application.css:
* { box-sizing: border-box; }

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #596579;
  --border: #cbd3df;
  --surface: #ffffff;
  --background: #f3f6fa;
  --primary: #2457a6;
  --primary-dark: #173d78;
  --danger: #a42626;
  --success-bg: #e7f6ed;
  --success-text: #17643b;
}

body {
  margin: 0;
  min-width: 18rem;
  background: var(--background);
  color: var(--ink);
  font: 1rem/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.page-shell { max-width:  seventyrem; margin: 0 auto; padding: 2.5rem 1.25rem; }
.page-header { margin-bottom: 2rem; }
.eyebrow { margin: 0 0 .35rem; color: var(--primary); font-size: .8rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .6rem; font-size: clamp(2rem, 5vw, 3rem); }
h2 { margin: 0 0 1.25rem; font-size: 1.35rem; }
.page-header p:last-child { max-width:  fortyrem; margin: 0; color: var(--muted); }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); gap: 1.5rem; align-items: start; }
.booking-form, .bookings-panel { padding: 1.5rem; border: 1px solid var(--border); border-radius: .8rem; background: var(--surface); box-shadow: 0 5px 20px rgba(23,32,51,.06); }
.required-note { margin: - .7rem 0 1.25rem; color: var(--muted); font-size: .88rem; }
.form-field { margin-bottom: 1rem; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
label { display: block; margin-bottom: .4rem; font-weight: 650; }
input, select { width: 100%; min-height: 2.75rem; padding: .6rem .7rem; border: 1px solid #8995a8; border-radius: .4rem; background: #fff; color: var(--ink); font: inherit; }
input:focus, select:focus, button:focus { outline: 3px solid #8db7f3; outline-offset: 2px; }
input[aria-invalid="true"], select[aria-invalid="true"] { border-color: var(--danger); }
.field-error { min-height: 1.25rem; margin: .25rem 0 0; color: var(--danger); font-size: .85rem; }
.primary-button, .cancel-button { border: 0; border-radius: .4rem; cursor: pointer; font: inherit; font-weight: 700; }
.primary-button { width: 100%; padding: .75rem 1rem; background: var(--primary); color: #fff; }
.primary-button:hover { background: var(--primary-dark); }
.form-status { min-height: 1.5rem; margin: .9rem 0 0; font-weight: 650; }
.form-status.success { color: var(--success-text); }
.panel-heading { display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
.count { display: grid; place-items: center; min-width: 2rem; height: 2rem; border-radius: 50%; background: #e4ebf7; color: var(--primary-dark); font-weight: 800; }
.booking-list { display: grid; gap: .9rem; }
.empty-state { margin: 0; color: var(--muted); }
.booking-card { padding: 1rem; border: 1px solid var(--border); border-left: 4px solid var(--primary); border-radius: .45rem; }
.booking-card.cancelled { border-left-color: #788394; opacity: .72; }
.booking-card h3 { margin: 0 0 .35rem; font-size: 1.05rem; }
.booking-card p { margin: .25rem 0; color: var(--muted); }
.booking-card .cancel-button { margin-top: .7rem; padding: .5rem .75rem; background: #fce8e8; color: var(--danger); }
.cancelled-label { color: var(--danger) !important; font-weight: 700; }
@media (max-width:  forty-eightrem) { .layout { grid-template-columns: 1fr; } }
@media (max-width:  thirtyrem) { .page-shell { padding: 1.5rem .8rem; } .booking-form, .bookings-panel { padding: 1.1rem; } .form-row { grid-template-columns: 1fr; gap: 0; } }

application.javascript:
const form = document.querySelector('#booking-form');
const list = document.querySelector('#booking-list');
const emptyState = document.querySelector('#empty-state');
const count = document.querySelector('#booking-count');
const formStatus = document.querySelector('#form-status');
const dateInput = document.querySelector('[data-testid="booking-date"]');
let bookings = [];

function getToday() {
  const now = new Date();
  const offsetDate = new Date(now.getTime() - now.getTimezoneOffset() * 60000);
  return offsetDate.toISOString().split('T')[0];
}

function setMinimumDate() {
  dateInput.min = getToday();
}

function clearErrors() {
  document.querySelectorAll('.field-error').forEach((element) => { element.textContent = ''; });
  form.querySelectorAll('[aria-invalid="true"]').forEach((element) => element.removeAttribute('aria-invalid'));
}

function showError(input, message) {
  input.setAttribute('aria-invalid', 'true');
  const error = document.querySelector(`#${input.id}-error`);
  if (error) error.textContent = message;
}

function validateForm() {
  clearErrors();
  const data = new FormData(form);
  const values = Object.fromEntries(data.entries());
  let valid = true;
  const fields = {
    name: document.querySelector('[data-testid="booking-name"]'),
    email: document.querySelector('[data-testid="booking-email"]'),
    date: dateInput,
    time: document.querySelector('[data-testid="booking-time"]'),
    type: document.querySelector('[data-testid="booking-type"]')
  };
  if (!values.name.trim()) { showError(fields.name, 'Enter the customer name.'); valid = false; }
  if (!values.email.trim()) { showError(fields.email, 'Enter an email address.'); valid = false; }
  else if (!fields.email.validity.valid) { showError(fields.email, 'Enter a valid email address.'); valid = false; }
  if (!values.date) { showError(fields.date, 'Choose an appointment date.'); valid = false; }
  else if (values.date < getToday()) { showError(fields.date, 'The appointment date cannot be in the past.'); valid = false; }
  if (!values.time) { showError(fields.time, 'Choose an appointment time.'); valid = false; }
  if (!values.type) { showError(fields.type, 'Choose an appointment type.'); valid = false; }
  return valid ? values : null;
}

function formatDate(date) {
  return new Date(`${date}T00:00:00`).toLocaleDateString(undefined, { dateStyle: 'medium' });
}

function createBookingCard(booking) {
  const card = document.createElement('article');
  card.className = 'booking-card';
  card.dataset.testid = 'booking';
  card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
  const heading = document.createElement('h3');
  heading.dataset.testid = 'booking-name-display';
  heading.textContent = booking.name;
  card.append(heading);
  const details = document.createElement('p');
  details.textContent = `${booking.type} • ${formatDate(booking.date)} at ${booking.time}`;
  card.append(details);
  const email = document.createElement('p');
  email.textContent = booking.email;
  card.append(email);
  if (booking.cancelled) {
    const status = document.createElement('p');
    status.className = 'cancelled-label';
    status.textContent = 'Cancelled';
    card.append(status);
  } else {
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'cancel-button';
    cancel.dataset.testid = 'booking-cancel';
    cancel.textContent = 'Cancel booking';
    cancel.addEventListener('click', () => cancelBooking(booking.id));
    card.append(cancel);
  }
  return card;
}

function renderBookings() {
  list.replaceChildren();
  if (!bookings.length) list.append(emptyState);
  bookings.forEach((booking) => list.append(createBookingCard(booking)));
  count.textContent = String(bookings.filter((booking) => !booking.cancelled).length);
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (booking) { booking.cancelled = true; renderBookings(); }
}

function handleSubmit(event) {
  event.preventDefault();
  const values = validateForm();
  if (!values) { formStatus.textContent = 'Please correct the highlighted fields.'; formStatus.className = 'form-status'; return; }
  bookings.push({ ...values, name: values.name.trim(), email: values.email.trim(), id: crypto.randomUUID(), cancelled: false });
  form.reset();
  clearErrors();
  formStatus.textContent = 'Booking created successfully.';
  formStatus.className = 'form-status success';
  renderBookings();
}

setMinimumDate();
form.addEventListener('submit', handleSubmit);
renderBookings();
